void kseq_destroy(kseq_t *seq) {
    if (seq == 0) return;
    free(seq->f->buf);
    free(seq->f);
    seq_free(&seq->seq);
    free(seq);
}

int kseq_read(kseq_t *seq) {
    int c, i = 0;
    seq_t *s = &seq->seq;

    if (seq->last_c == 0) {
        while ((c = gzgetc(seq->f->fp)) != -1 && c != '>' && c != '@') {}
        if (c == -1) return -1;
        seq->last_c = c;
    }

    s->comment[0] = s->name[0] = s->seq[0] = s->qual[0] = 0;
    s->n = 0;

    if (seq->last_c == '>' || seq->last_c == '@') {
        int is_fastq = (seq->last_c == '@');
        i = 0;
        while ((c = gzgetc(seq->f->fp)) != -1 && c != '\n') {
            if (i >= s->m - 1) {
                s->m *= 2;
                s->name = realloc(s->name, s->m);
            }
            s->name[i++] = c;
        }
        s->name[i] = 0;

        while ((c = gzgetc(seq->f->fp)) != -1 && c != '>' && c != '@' && c != '+') {
            if (c == '\n') continue;
            if (s->n >= s->m - 1) {
                s->m *= 2;
                s->seq = realloc(s->seq, s->m);
            }
            s->seq[s->n++] = c;
        }
        s->seq[s->n] = 0;

        if (is_fastq) {
            if (c == '+') {
                i = 0;
                while ((c = gzgetc(seq->f->fp)) != -1 && c != '\n') {
                    if (i >= s->m - 1) {
                        s->m *= 2;
                        s->comment = realloc(s->comment, s->m);
                    }
                    s->comment[i++] = c;
                }
                s->comment[i] = 0;

                int j = 0;
                while ((c = gzgetc(seq->f->fp)) != -1 && j < s->n) {
                    if (c == '\n') continue;
                    if (j >= s->m - 1) {
                        s->m *= 2;
                        s->qual = realloc(s->qual, s->m);
                    }
                    s->qual[j++] = c;
                }
                s->qual[j] = 0;
            }
        }

        seq->last_c = c;
    }

    return (s->n > 0 ? s->n : -1);
}

