        while ((c = gzgetc(fp)) != -1 && c != '>' && c != '@') {}
        if (c == -1) {
            *at_eof = 1;
            return -1;
        }
        last_c = c;
    }

    int is_fastq = (last_c == '@');

    i = 0;
    while ((c = gzgetc(fp)) != -1 && c != '\n') {
        if (i >= (int)strlen(seq->name) + 200) {
            seq->name = realloc(seq->name, i + 256);
        }
        seq->name[i++] = c;
    }
    seq->name[i] = 0;

    while ((c = gzgetc(fp)) != -1 && c != '>' && c != '@' && c != '+') {
        if (c == '\n') continue;
        if (seq->l >= seq->m - 1) {
            seq_expand(seq, seq->m * 2);
        }
        seq->s[seq->l++] = c;
    }
    seq->s[seq->l] = 0;

    if (is_fastq && c == '+') {
        i = 0;
        while ((c = gzgetc(fp)) != -1 && c != '\n') {
            if (i >= (int)strlen(seq->comm) + 200) {
                seq->comm = realloc(seq->comm, i + 256);
            }
            seq->comm[i++] = c;
        }
        seq->comm[i] = 0;

        int j = 0;
        while ((c = gzgetc(fp)) != -1 && j < seq->l) {
            if (c == '\n') continue;
            if (j >= seq->m - 1) {
                seq_expand(seq, seq->m * 2);
            }
            seq->q[j++] = c;
        }
        seq->q[j] = 0;
    }

    return seq->l;
