            if (i + 1 < argc) n_sample = atoi(argv[++i]);
            break;
        }
    }

    if (n_sample <= 0) {
        fprintf(stderr, "Usage: seqtk sample [-s seed] <in.fa|in.fq> [number]\n");
        return 1;
    }

    srand(seed);

    int n_seq = 0;
    indices = malloc(sizeof(int) * 100000);

    int *selected = malloc(sizeof(int) * n_sample);
    for (i = 0; i < n_sample; ++i) selected[i] = -1;

    while (kseq_read(&seq, fp, &at_eof, last_c) >= 0) {
        last_c = 0;
        n_seq++;

        if (n_seq <= n_sample) {
            selected[n_seq - 1] = n_seq - 1;
        } else {
            int r = rand() % n_seq;
            if (r < n_sample) {
                for (j = 0; j < n_sample; ++j) {
                    if (selected[j] == -1) {
                        selected[j] = n_seq - 1;
                        break;
                    }
                }
            }
        }
    }

    gzclose(fp);
    fp = gzopen_check(argv[1], "r");

    int k = 0;
    n_seq = 0;
    while (kseq_read(&seq, fp, &at_eof, last_c) >= 0) {
        last_c = 0;

        for (j = 0; j < n_sample; ++j) {
            if (selected[j] == n_seq) {
                if (seq.q[0]) {
                    printf("@%s\n%s\n+%s\n%s\n", seq.name, seq.s, seq.comm, seq.q);
                } else {
                    printf(">%s\n%s\n", seq.name, seq.s);
                }
                break;
            }
        }
        n_seq++;
    }

    gzclose(fp);
    free(seq.s);
    free(seq.q);
    free(seq.name);
    free(seq.comm);
    free(selected);
    free(indices);
    return 0;
}

