typedef struct {
    char *s, *q;
    int l, m;
    char *name, *comm;
    int n_a[256];
} seq_t;

gzFile gzopen_check(const char *fn, const char *mode) {
    gzFile fp = gzopen(fn, mode);
    if (fp == NULL) {
        fprintf(stderr, "ERROR: cannot open file '%s'\n", fn);
        exit(1);
    }
    return fp;
