void reverse_complement(char *s, int len) {
    int i, j;
    char c;
    for (i = 0, j = len - 1; i < j; ++i, --j) {
        c = seq_comp_table[(int)s[i]];
        s[i] = seq_comp_table[(int)s[j]];
        s[j] = c;
    }
    if (i == j) s[i] = seq_comp_table[(int)s[i]];
}

int seq_main(int argc, char *argv[]) {
    gzFile fp;
    kseq_t *kseq;
    int i, c, qual_thres = 0, line_len = 0, is_a = 0, is_r = 0, is_q = 0;
    int qual64 = 33, is_U = 0, is_C = 0, is_N = 0;
    char mask_c = 'N';

    for (i = 1; i < argc; ++i) {
        if (argv[i][0] == '-') {
            c = argv[i][1];
            if (c == 'a') is_a = 1;
            else if (c == 'r') is_r = 1;
            else if (c == 'U') is_U = 1;
            else if (c == 'C') is_C = 1;
            else if (c == 'l') {
                if (i + 1 < argc) line_len = atoi(argv[++i]);
            }
            else if (c == 'q') {
                if (i + 1 < argc) qual_thres = atoi(argv[++i]);
            }
            else if (c == 'Q') {
                if (i + 1 < argc) qual64 = atoi(argv[++i]);
            }
            else if (c == 'n') {
                if (i + 1 < argc) {
                    mask_c = argv[++i][0];
                    is_N = 1;
                }
            }
            else if (c == 'M') {
                if (i + 1 < argc) i++;
            }
        } else {
            fp = gzopen_check(argv[i], "r");
            break;
        }
    }

    kseq = kseq_init(fp);

    while (kseq_read(kseq) >= 0) {
        seq_t *seq = &kseq->seq;

        if (is_r) {
            if (seq->q[0]) {
                reverse_complement(seq->q, seq->l);
            }
            reverse_complement(seq->s, seq->l);
        }

        if (is_U) {
            for (i = 0; i < seq->l; ++i) {
                seq->s[i] = toupper(seq->s[i]);
            }
        }

        if (is_C) {
            for (i = 0; i < seq->l; ++i) {
                seq->s[i] = tolower(seq->s[i]);
            }
        }

        if (qual_thres > 0 && seq->q[0]) {
            for (i = 0; i < seq->l; ++i) {
                int q = seq->q[i] - qual64;
                if (q < qual_thres) {
                    seq->s[i] = tolower(seq->s[i]);
                }
            }
        }

        if (is_a || seq->q[0] == 0) {
            printf(">%s\n", seq->name);
            if (line_len > 0) {
                for (i = 0; i < seq->l; i += line_len) {
                    int len = (i + line_len < seq->l) ? line_len : seq->l - i;
                    printf("%.*s\n", len, seq->s + i);
                }
            } else {
                printf("%s\n", seq->s);
            }
        } else {
            printf("@%s\n%s\n+%s\n%s\n", seq->name, seq->s, seq->comm, seq->q);
        }
    }

    kseq_destroy(kseq);
    gzclose(fp);
    return 0;
}

