int fqchk_main(int argc, char *argv[]) {
    gzFile fp;
    kseq_t *kseq;
    int i, j;
    int min_len = INT_MAX, max_len = 0;
    double sum_len = 0, sum_q = 0;
    int **cnt, *pos_cnt;
    int n_seq = 0;

    if (argc < 2) {
        fprintf(stderr, "Usage: seqtk fqchk <in.fq>\n");
        return 1;
    }

    fp = gzopen_check(argv[1], "r");
    kseq = kseq_init(fp);

    cnt = malloc(256 * sizeof(int*));
    for (i = 0; i < 256; ++i) cnt[i] = calloc(1000, sizeof(int));

    pos_cnt = calloc(1000, sizeof(int));

    while (kseq_read(kseq) >= 0) {
        seq_t *seq = &kseq->seq;
        n_seq++;

        if (seq->l < min_len) min_len = seq->l;
        if (seq->l > max_len) max_len = seq->l;

        sum_len += seq->l;

        for (i = 0; i < seq->l; ++i) {
            if (seq->q[0]) {
                sum_q += (double)(seq->q[i] - 33);
                cnt[(int)seq->s[i]][i]++;
            }
            pos_cnt[i]++;
        }
    }

    printf("min_len: %d; max_len: %d; avg_len: %.2f; ", min_len, max_len, sum_len / n_seq);

    int n_qual = 0;
    for (i = 0; i < 256; ++i) {
        int has = 0;
        for (j = 0; j < max_len; ++j) {
            if (cnt[i][j] > 0) { has = 1; break; }
        }
        if (has) n_qual++;
    }

    printf("%d distinct quality values\n", n_qual);
    printf("POS\t#bases\t%%A\t%%C\t%%G\t%%T\t%%N\tavgQ\terrQ\t%%low\t%%high\n");

    for (i = 0; i < max_len; ++i) {
        int a = cnt['A'][i] + cnt['a'][i];
        int c = cnt['C'][i] + cnt['c'][i];
        int g = cnt['G'][i] + cnt['g'][i];
        int t = cnt['T'][i] + cnt['t'][i];
        int n = cnt['N'][i] + cnt['n'][i];

        double avgQ = 0, errQ = 0;
        for (j = 0; j < 256; ++j) {
            if (cnt[j][i] > 0) {
                avgQ += (double)(j - 33) * cnt[j][i];
            }
        }
        if (pos_cnt[i] > 0) avgQ /= pos_cnt[i];

        for (j = 0; j < 256; ++j) {
            if (cnt[j][i] > 0) {
                errQ += pow(10.0, -((double)(j - 33) / 10.0)) * cnt[j][i];
            }
        }
        if (pos_cnt[i] > 0) errQ /= pos_cnt[i];
        errQ = -10.0 * log10(errQ + 1e-10);

        printf("%d\t%d\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\n",
               i + 1, pos_cnt[i],
               100.0 * a / (pos_cnt[i] + 1e-10),
               100.0 * c / (pos_cnt[i] + 1e-10),
               100.0 * g / (pos_cnt[i] + 1e-10),
               100.0 * t / (pos_cnt[i] + 1e-10),
               100.0 * n / (pos_cnt[i] + 1e-10),
               avgQ, errQ, 0.0, 100.0);
    }

    kseq_destroy(kseq);
    gzclose(fp);
    for (i = 0; i < 256; ++i) free(cnt[i]);
    free(cnt);
    free(pos_cnt);
    return 0;
}

