            }
        } else {
            fp = gzopen_check(argv[i], "r");
            break;
        }
    }

    kseq = kseq_init(fp);

    while (kseq_read(kseq) >= 0) {
        seq_t *seq = &kseq->seq;

        if (is_r) {
            if (seq->q[0]) {
                reverse_complement(seq->q, seq->l);
            }
            reverse_complement(seq->s, seq->l);
        }

        if (is_U) {
            for (i = 0; i < seq->l; ++i) {
                seq->s[i] = toupper(seq->s[i]);
            }
        }

        if (is_C) {
            for (i = 0; i < seq->l; ++i) {
                seq->s[i] = tolower(seq->s[i]);
            }
        }

        if (qual_thres > 0 && seq->q[0]) {
            for (i = 0; i < seq->l; ++i) {
                int q = seq->q[i] - qual64;
                if (q < qual_thres) {
                    seq->s[i] = tolower(seq->s[i]);
                }
            }
        }

        if (is_a || seq->q[0] == 0) {
            printf(">%s\n", seq->name);
            if (line_len > 0) {
                for (i = 0; i < seq->l; i += line_len) {
                    int len = (i + line_len < seq->l) ? line_len : seq->l - i;
                    printf("%.*s\n", len, seq->s + i);
                }
            } else {
                printf("%s\n", seq->s);
            }
        } else {
            printf("@%s\n%s\n+%s\n%s\n", seq->name, seq->s, seq->comm, seq->q);
        }
    }

    kseq_destroy(kseq);
    gzclose(fp);
    return 0;
}

