            fp = gzopen_check(argv[i], "r");
            if (i + 1 < argc) n_sample = atoi(argv[++i]);
            break;
        }
    }

    if (n_sample <= 0) {
        fprintf(stderr, "Usage: seqtk sample [-s seed] <in.fa|in.fq> [number]\n");
        return 1;
    }

    srand(seed);

    kseq = kseq_init(fp);

    int n_seq = 0;
    selected = malloc(sizeof(int) * 100000);
    for (i = 0; i < 100000; ++i) selected[i] = -1;

    while (kseq_read(kseq) >= 0) {
        n_seq++;

        if (n_seq <= n_sample) {
            selected[n_seq - 1] = n_seq - 1;
        } else {
            int r = rand() % n_seq;
            if (r < n_sample) {
                for (j = 0; j < n_sample; ++j) {
                    if (selected[j] == -1 || selected[j] >= n_seq - 1) {
                        selected[j] = n_seq - 1;
                        break;
                    }
                }
            }
        }
    }

    kseq_destroy(kseq);
    gzclose(fp);

    fp = gzopen_check(argv[1], "r");
