    int k = 0;
    n_seq = 0;
    while (kseq_read(kseq) >= 0) {
        seq_t *seq = &kseq->seq;

        for (j = 0; j < n_sample; ++j) {
            if (selected[j] == n_seq) {
                if (seq->q[0]) {
                    printf("@%s\n%s\n+%s\n%s\n", seq->name, seq->s, seq->comm, seq->q);
