#define VERSION "1.5-r133"
#define SEQTK_MAX_QUAL 127
#define MAXLINE 1000000

typedef struct {
    char *s, *q;
    int l, m;
    char *name, *comm;
    int n_a[256];
} seq_t;

typedef struct {
    gzFile fp;
    unsigned char *buf;
    int n, m;
} kseq_buf_t;

typedef struct {
    int n;
    unsigned char last_c;
    kseq_buf_t *f;
    seq_t seq;
} kseq_t;

gzFile gzopen_check(const char *fn, const char *mode) {
    gzFile fp = gzopen(fn, mode);
    if (fp == NULL) {
        fprintf(stderr, "ERROR: cannot open file '%s'\n", fn);
        exit(1);
    }
    return fp;
}

void seq_init(seq_t *s) {
    s->m = 256;
    s->l = 0;
    s->s = malloc(s->m);
    s->q = malloc(s->m);
    s->name = malloc(s->m);
    s->comm = malloc(s->m);
    memset(s->n_a, 0, sizeof(s->n_a));
}

void seq_expand(seq_t *s, int len) {
    if (s->m < len + 1) {
        s->m = len + 1;
        s->s = realloc(s->s, s->m);
        s->q = realloc(s->q, s->m);
    }
}

kseq_t *kseq_init(gzFile fp) {
    kseq_t *s;
    s = (kseq_t *)calloc(1, sizeof(kseq_t));
    s->f = (kseq_buf_t *)calloc(1, sizeof(kseq_buf_t));
    s->f->fp = fp;
    s->f->buf = (unsigned char *)malloc(4096);
    s->f->m = 4096;
    s->f->n = 0;
    seq_init(&s->seq);
    return s;
}

void kseq_destroy(kseq_t *seq) {
    if (seq == 0) return;
    free(seq->f->buf);
    free(seq->f);
    if (seq->seq.s) free(seq->seq.s);
    if (seq->seq.q) free(seq->seq.q);
    if (seq->seq.name) free(seq->seq.name);
    if (seq->seq.comm) free(seq->seq.comm);
    free(seq);
}

static int kseq_read_char(kseq_t *seq) {
    if (seq->f->n == 0) {
        seq->f->n = gzread(seq->f->fp, seq->f->buf, seq->f->m);
        if (seq->f->n <= 0) return -1;
        seq->f->n = 0;
    }
    if (seq->f->n >= seq->f->m) {
        seq->f->n = 0;
        return kseq_read_char(seq);
    }
    return seq->f->buf[seq->f->n++];
}

int kseq_read(kseq_t *seq) {
    int c, i;
    seq->seq.l = 0;
    seq->seq.name[0] = seq->seq.comm[0] = seq->seq.s[0] = seq->seq.q[0] = 0;

    if (seq->last_c == 0) {
        while ((c = gzgetc(seq->f->fp)) != -1 && c != '>' && c != '@') {}
        if (c == -1) return -1;
        seq->last_c = c;
    }

    int is_fastq = (seq->last_c == '@');

    i = 0;
    while ((c = gzgetc(seq->f->fp)) != -1 && c != '\n') {
        if (i >= 199) {
            seq->seq.name = realloc(seq->seq.name, i + 256);
        }
        seq->seq.name[i++] = c;
    }
    seq->seq.name[i] = 0;

    while ((c = gzgetc(seq->f->fp)) != -1 && c != '>' && c != '@' && c != '+') {
        if (c == '\n') continue;
        if (seq->seq.l >= seq->seq.m - 1) {
            seq_expand(&seq->seq, seq->seq.m * 2);
        }
        seq->seq.s[seq->seq.l++] = c;
    }
    seq->seq.s[seq->seq.l] = 0;

    if (is_fastq && c == '+') {
        i = 0;
        while ((c = gzgetc(seq->f->fp)) != -1 && c != '\n') {
            if (i >= 199) {
                seq->seq.comm = realloc(seq->seq.comm, i + 256);
            }
            seq->seq.comm[i++] = c;
        }
        seq->seq.comm[i] = 0;

        int j = 0;
        while ((c = gzgetc(seq->f->fp)) != -1 && j < seq->seq.l) {
            if (c == '\n') continue;
            if (j >= seq->seq.m - 1) {
                seq_expand(&seq->seq, seq->seq.m * 2);
            }
            seq->seq.q[j++] = c;
        }
        seq->seq.q[j] = 0;
    }

    seq->last_c = c;
    return seq->seq.l;
}

