#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <time.h>
#include <math.h>
#include <zlib.h>
#include <sys/stat.h>
#include <limits.h>

#define VERSION "1.5-r133"

typedef struct {
    char *name, *comment, *seq, *qual;
    int m, n;
} seqrec_t;

void seq_init(seqrec_t *s) {
    s->m = 256;
    s->n = 0;
    s->name = malloc(s->m);
    s->comment = malloc(s->m);
    s->seq = malloc(s->m);
    s->qual = malloc(s->m);
}

void seq_extend(seqrec_t *s, int len) {
    while (s->m <= len) {
        s->m *= 2;
        s->seq = realloc(s->seq, s->m);
        s->qual = realloc(s->qual, s->m);
    }
}

int read_seq(gzFile fp, seqrec_t *s, int *at_eof, int last_c) {
    int c;
    s->n = 0;
    s->name[0] = s->comment[0] = s->seq[0] = s->qual[0] = 0;

    if (last_c == 0) {
        while ((c = gzgetc(fp)) != -1 && c != '>' && c != '@') {}
        if (c == -1) {
            *at_eof = 1;
            return -1;
        }
        last_c = c;
    }

    int is_fastq = (last_c == '@');

    // read name
    int i = 0;
    while ((c = gzgetc(fp)) != -1 && c != '\n') {
        if (i >= 199) s->name = realloc(s->name, i + 256);
        s->name[i++] = c;
    }
    s->name[i] = 0;

    // read sequence
    while ((c = gzgetc(fp)) != -1 && c != '>' && c != '@' && c != '+') {
        if (c == '\n') continue;
        seq_extend(s, s->n + 2);
        s->seq[s->n++] = c;
    }
    s->seq[s->n] = 0;

    // read quality if FASTQ
    if (is_fastq && c == '+') {
        i = 0;
        while ((c = gzgetc(fp)) != -1 && c != '\n') {
            if (i >= 199) s->comment = realloc(s->comment, i + 256);
            s->comment[i++] = c;
        }
        s->comment[i] = 0;

        int j = 0;
        while ((c = gzgetc(fp)) != -1 && j < s->n) {
            if (c == '\n') continue;
            seq_extend(s, j + 2);
            s->qual[j++] = c;
        }
        s->qual[j] = 0;
    }

    return s->n;
}

