    int i, j;
    char c;
    for (i = 0, j = len - 1; i < j; ++i, --j) {
        c = seq_comp[(int)s[i]];
        s[i] = seq_comp[(int)s[j]];
        s[j] = c;
    }
    if (i == j) s[i] = seq_comp[(int)s[i]];
}

int seq_main(int argc, char *argv[]) {
    int i, qual_thres = 0, line_len = 0, is_a = 0, is_r = 0, is_U = 0, is_C = 0;
    int qual64 = 33;
    const char *filename = NULL;

    for (i = 1; i < argc; ++i) {
        if (argv[i][0] == '-') {
            if (argv[i][1] == 'a') is_a = 1;
            else if (argv[i][1] == 'r') is_r = 1;
            else if (argv[i][1] == 'U') is_U = 1;
            else if (argv[i][1] == 'C') is_C = 1;
            else if (argv[i][1] == 'l') {
                if (i + 1 < argc) line_len = atoi(argv[++i]);
            }
            else if (argv[i][1] == 'q') {
                if (i + 1 < argc) qual_thres = atoi(argv[++i]);
            }
            else if (argv[i][1] == 'Q') {
                if (i + 1 < argc) qual64 = atoi(argv[++i]);
            }
            else if (argv[i][1] == 'n') {
                if (i + 1 < argc) i++;
            }
            else if (argv[i][1] == 'M') {
                if (i + 1 < argc) i++;
            }
        } else {
            filename = argv[i];
            break;
        }
    }

    gzFile fp = gzopen(filename, "rb");
    if (!fp) {
        fprintf(stderr, "Cannot open file: %s\n", filename);
        return 1;
    }

    seqrec_t s;
    seq_init(&s);

    int at_eof = 0, last_c = 0;
    while (read_seq(fp, &s, &at_eof, last_c) >= 0) {
        last_c = 0;

        if (is_r) {
            if (s.qual[0]) revcomp(s.qual, s.n);
            revcomp(s.seq, s.n);
        }

        if (is_U) {
            for (i = 0; i < s.n; ++i) s.seq[i] = toupper(s.seq[i]);
        }

        if (is_C) {
            for (i = 0; i < s.n; ++i) s.seq[i] = tolower(s.seq[i]);
        }

        if (qual_thres > 0 && s.qual[0]) {
            for (i = 0; i < s.n; ++i) {
                if (s.qual[i] - qual64 < qual_thres) {
                    s.seq[i] = tolower(s.seq[i]);
                }
            }
        }

        if (is_a || !s.qual[0]) {
            printf(">%s\n", s.name);
            if (line_len > 0) {
                for (i = 0; i < s.n; i += line_len) {
                    int len = (i + line_len < s.n) ? line_len : s.n - i;
                    printf("%.*s\n", len, s.seq + i);
                }
            } else {
                printf("%s\n", s.seq);
            }
        } else {
            printf("@%s\n%s\n+%s\n%s\n", s.name, s.seq, s.comment, s.qual);
        }
    }

    gzclose(fp);
    free(s.name);
    free(s.comment);
    free(s.seq);
    free(s.qual);
    return 0;
}

