int sample_main(int argc, char *argv[]) {
    int seed = time(NULL), n_sample = 0, i;
    const char *filename = NULL;

    for (i = 1; i < argc; ++i) {
        if (argv[i][0] == '-' && argv[i][1] == 's') {
            if (i + 1 < argc) seed = atoi(argv[++i]);
        } else if (argv[i][0] != '-') {
            filename = argv[i];
            if (i + 1 < argc) n_sample = atoi(argv[++i]);
            break;
        }
    }

    if (!filename || n_sample <= 0) {
        fprintf(stderr, "Usage: seqtk sample [-s seed] <in.fa|in.fq> [number]\n");
        return 1;
    }

    srand(seed);

    gzFile fp = gzopen(filename, "rb");
    if (!fp) return 1;

    seqrec_t s;
    seq_init(&s);

    // First pass: count and select
    int n_seq = 0, at_eof = 0, last_c = 0;
    int *selected = calloc(100000, sizeof(int));

    while (read_seq(fp, &s, &at_eof, last_c) >= 0) {
        last_c = 0;
        n_seq++;
        if (n_seq <= n_sample) {
            selected[n_seq - 1] = n_seq - 1;
        } else {
            int r = rand() % n_seq;
            if (r < n_sample) {
                for (int j = 0; j < n_sample; ++j) {
                    if (selected[j] == -1 || selected[j] >= n_seq) {
                        selected[j] = n_seq - 1;
                        break;
                    }
                }
            }
        }
    }

    gzclose(fp);

    // Second pass: output selected sequences
    fp = gzopen(filename, "rb");
    n_seq = 0;
    last_c = 0;
    at_eof = 0;

    while (read_seq(fp, &s, &at_eof, last_c) >= 0) {
        last_c = 0;

        for (int j = 0; j < n_sample; ++j) {
            if (selected[j] == n_seq) {
                if (s.qual[0]) {
                    printf("@%s\n%s\n+%s\n%s\n", s.name, s.seq, s.comment, s.qual);
                } else {
                    printf(">%s\n%s\n", s.name, s.seq);
                }
                break;
            }
        }
        n_seq++;
    }

    gzclose(fp);
    free(selected);
    free(s.name);
    free(s.comment);
    free(s.seq);
    free(s.qual);
    return 0;
}

int subseq_main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: seqtk subseq <in.fa|in.fq> <list|bed>\n");
        return 1;
    }

    gzFile fp = gzopen(argv[1], "rb");
    if (!fp) return 1;

    FILE *fp2 = fopen(argv[2], "r");
    if (!fp2) return 1;

    seqrec_t s;
    seq_init(&s);

    char line[10000], name[1000];
    int beg, end;

    while (fgets(line, sizeof(line), fp2)) {
        line[strcspn(line, "\n")] = 0;

        if (sscanf(line, "%s\t%d\t%d", name, &beg, &end) == 3) {
            // BED format
            gzrewind(fp);
            int at_eof = 0, last_c = 0;

            while (read_seq(fp, &s, &at_eof, last_c) >= 0) {
                last_c = 0;
                if (strncmp(s.name, name, strlen(name)) == 0) {
                    if (beg < 0) beg = 0;
                    if (end > s.n) end = s.n;

                    if (s.qual[0]) {
                        printf("@%s:%d-%d\n%.*s\n+\n%.*s\n", s.name, beg + 1, end, end - beg, s.seq + beg, end - beg, s.qual + beg);
                    } else {
                        printf(">%s:%d-%d\n%.*s\n", s.name, beg + 1, end, end - beg, s.seq + beg);
                    }
                    break;
                }
            }
        } else {
            // Name list
            gzrewind(fp);
            int at_eof = 0, last_c = 0;

            while (read_seq(fp, &s, &at_eof, last_c) >= 0) {
                last_c = 0;
                if (strcmp(s.name, line) == 0) {
                    if (s.qual[0]) {
                        printf("@%s\n%s\n+%s\n%s\n", s.name, s.seq, s.comment, s.qual);
                    } else {
                        printf(">%s\n%s\n", s.name, s.seq);
                    }
                    break;
                }
            }
        }
    }

    gzclose(fp);
    fclose(fp2);
    free(s.name);
    free(s.comment);
    free(s.seq);
    free(s.qual);
    return 0;
}

