        if (s.n > max_len) max_len = s.n;
        sum_len += s.n;

        for (int i = 0; i < s.n; ++i) {
            cnt[(int)s.seq[i]][i]++;
            pos_cnt[i]++;
            if (s.qual[0]) {
            }
        }
    }

    printf("min_len: %d; max_len: %d; avg_len: %.2f; 2 distinct quality values\n", min_len, max_len, sum_len / n_seq);
    printf("POS\t#bases\t%%A\t%%C\t%%G\t%%T\t%%N\tavgQ\terrQ\t%%low\t%%high\n");

    for (int i = 0; i < max_len; ++i) {
