int mergepe_main(int argc, char *argv[]) {
    if (argc < 3) return 1;

    gzFile fp1 = gzopen(argv[1], "rb");
    gzFile fp2 = gzopen(argv[2], "rb");
    if (!fp1 || !fp2) return 1;

    seqrec_t s1, s2;
    seq_init(&s1);
