    int at_eof1 = 0, last_c1 = 0, at_eof2 = 0, last_c2 = 0;
    while (read_seq(fp1, &s1, &at_eof1, last_c1) >= 0 && read_seq(fp2, &s2, &at_eof2, last_c2) >= 0) {
        last_c1 = last_c2 = 0;
        if (s1.qual[0]) {
            printf("@%s\n%s\n+%s\n%s\n", s1.name, s1.seq, s1.comment, s1.qual);
